// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Ensure the owner is set by checking before any state-modifying call
        // The general rule: after deployment, owner should equal address(this) (the deployer)
        assertTrue(c.owner() == address(this));
        // Now call sendMoney to trigger the mutated behavior
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));
        // After any such call, the rule about owner remains the same (owner should not change)
        assertTrue(c.owner() == address(this));
    }
}

